with cleaned as (select *, case when monthly_fee >= 182 then 'High' when monthly_fee >= 90 then 'Medium' else 'Low' end as monthly_fee_band from subscriptions where customer_id is not null) select status, date_trunc('week', start_date) as week_start, avg(monthly_fee) as avg_monthly_fee, round(avg(monthly_fee), 2) as avg_monthly_fee_2, size(collect_set(status)) as num_status, dense_rank() over (partition by status order by round(avg(monthly_fee), 2) desc) as avg_monthly_fee_2_dense_rank from cleaned group by status, date_trunc('week', start_date) order by status;
